package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute buttonPauseToggle : Boolean;
    in attribute elapsedMilliseconds : Integer;
    attribute paused : Boolean := false;
    attribute prev_buttonPauseToggle : Boolean := false;
    attribute accumRunMs : Integer := 0;
    attribute soundRemainingMs : Integer := 0;
    attribute firstSoundPending : Boolean := true;
    perform action tick {
      first start;
      then if ((buttonPauseToggle) and ((not prev_buttonPauseToggle))) {
        first start;
        then assign paused := (not paused);
      }
      then assign prev_buttonPauseToggle := buttonPauseToggle;
      then if (not paused) {
        first start;
        then if ((soundRemainingMs) > (0)) {
          first start;
          then assign soundRemainingMs := soundRemainingMs - elapsedMilliseconds;
          then if ((soundRemainingMs) <= (elapsedMilliseconds)) {
            first start;
            then assign soundRemainingMs := 0;
          }
        }
        then if ((soundRemainingMs) == (0)) {
          first start;
          then assign accumRunMs := accumRunMs + elapsedMilliseconds;
          then if ((accumRunMs) >= (3000)) {
            first start;
            then assign accumRunMs := 0;
            then assign soundRemainingMs := 100;
          }
        }
      }
    }
    out attribute buzzerToneHz : Integer = (if (((not paused)) and (((soundRemainingMs) > (0)))) ? 1000 else 0);
  }
  part system : Controller;
}

